scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsCodeQuality(ast).deprecatedJson();
    var report = new global.EcsReport(engine, {
        ruleId: 'JS-003',
        title: 'Deprecated JSON API',
        recommendation: 'Use the native JSON.stringify() and JSON.parse() instead of new JSON().encode/decode, evalJSON(), Object.toJSON() or JSONParser.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
